-- GENERATED by osquery/tools/build.py. Do not edit.
-- Source of truth is osquery/queries/*.sql; edit there and rebuild.
-- Columns, in order: kind, id, ver, loc, extra, perms
--
-- PLATFORM: linux. Run this only on linux. The tables named here do not all
-- exist elsewhere, and osqueryi given a missing table returns "[\n\n]" -- valid,
-- empty, entirely plausible JSON -- and exits 1. Every other artifact in dist/ is for a
-- different platform and is NOT a superset of this one. bin/discover picks by `uname -s`.

-- from browser.sql
SELECT 'ext' AS kind, identifier AS id, version AS ver, profile_path AS loc,
       browser_type
         || CASE WHEN referenced = 0 THEN ',unreferenced'
                 WHEN from_webstore != 'true'
                   THEN ',sideloaded:' || IFNULL(manifest_hash, '')
                 ELSE '' END
         AS extra,
       permissions
         || CASE WHEN manifest_json LIKE '%<all_urls>%' THEN ',<all_urls>' ELSE '' END
         AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN chrome_extensions USING (uid)

UNION ALL

-- from desktop-linux.sql
SELECT 'desktop' AS kind, filename AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/usr/share/applications/%.desktop'
     OR path LIKE '/usr/local/share/applications/%.desktop'
UNION ALL
-- Per-user entries, where a user-integrated AppImage lands. /root needs its own pattern
-- (CLAUDE.md, Traps).
SELECT 'desktop', filename, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.local/share/applications/%.desktop'
     OR path LIKE '/root/.local/share/applications/%.desktop'

UNION ALL

-- from filesystem-linux.sql
SELECT 'file' AS kind, path AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/home/%/.local/bin/%'
     OR path LIKE '/root/.local/bin/%'
UNION ALL
-- STATE DIRECTORIES. The trailing slash is load-bearing, and `.` and `..` are excluded,
-- as in filesystem.sql.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE (path LIKE '/home/%/.%/' OR path LIKE '/root/.%/')
    AND path NOT LIKE '%/./'
    AND path NOT LIKE '%/../'
UNION ALL
-- PYTHON-PACKAGED AGENTS, through pipx's and uv's tool directories, as in filesystem.sql.
SELECT 'file', path, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.local/pipx/venvs/%/'
     OR path LIKE '/home/%/.local/share/uv/tools/%/'
     OR path LIKE '/root/.local/pipx/venvs/%/'
     OR path LIKE '/root/.local/share/uv/tools/%/'
-- KNOWN GAP: `npx`/`bunx` runs, as in filesystem.sql.

UNION ALL

-- from jetbrains.sql
SELECT 'jbplugin' AS kind, regex_match(path, '([^/]+)/?$', 1) AS id, version AS ver,
       path AS loc, vendor AS extra, '' AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN jetbrains_plugins USING (uid)

UNION ALL

-- from native-messaging-linux.sql
SELECT 'nmh' AS kind, filename AS id, '' AS ver, path AS loc, '' AS extra, '' AS perms
  FROM file
  WHERE path LIKE '/home/%/.config/%/NativeMessagingHosts/%.json'
     OR path LIKE '/root/.config/%/NativeMessagingHosts/%.json'
UNION ALL
-- Firefox: lower-case in the user scope too, and not under .config.
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/home/%/.mozilla/native-messaging-hosts/%.json'
     OR path LIKE '/root/.mozilla/native-messaging-hosts/%.json'
UNION ALL
-- The system scope: /etc/opt/chrome, /etc/chromium and /usr/lib/mozilla, at two depths.
SELECT 'nmh', filename, '', path, '', '' FROM file
  WHERE path LIKE '/etc/%/native-messaging-hosts/%.json'
     OR path LIKE '/etc/opt/%/native-messaging-hosts/%.json'
     OR path LIKE '/usr/lib/%/native-messaging-hosts/%.json'

UNION ALL

-- from packages-linux.sql
SELECT 'deb' AS kind, name AS id, version AS ver, '' AS loc, arch AS extra, '' AS perms
  FROM deb_packages
  WHERE status LIKE '%ok installed'
UNION ALL
-- rpm's database holds installed packages only, so it needs no status filter. `vendor`
-- ships in `extra`: the one route whose artifact names its own publisher.
SELECT 'rpm', name, version, '', vendor, '' FROM rpm_packages

UNION ALL

-- from packages.sql
SELECT 'npm' AS kind, name AS id, version AS ver, path AS loc, '' AS extra, '' AS perms
  FROM npm_packages
  WHERE path NOT LIKE '%/node_modules/%/node_modules/%'
UNION ALL
-- BUN GLOBALS. npm_packages searches npm, nvm, asdf, fnm, mise and volta prefixes and never
-- ~/.bun (npm_packages.cpp at 5.23.1). Its `directory` constraint means "the directory that
-- holds node_modules", pushed down once per home. The homes are queries/browser.sql's, and
-- a `file` directory row ends in '/', so it is trimmed first.
--
-- `extra` IS 'bun' because bun hoists a global's dependencies flat beside it, where the
-- structural predicate cannot drop them: it tells a reader why one global brought several
-- rows. Not covered: BUN_INSTALL_GLOBAL_DIR or bunfig's globalDir.
SELECT 'npm', np.name, np.version, np.path, 'bun', ''
  FROM (SELECT directory AS home FROM users
        UNION
        SELECT rtrim(path, '/') FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') h
       CROSS JOIN npm_packages np ON np.directory = h.home || '/.bun/install/global'
  WHERE np.path NOT LIKE '%/node_modules/%/node_modules/%'

UNION ALL

-- from ports.sql
SELECT 'port' AS kind, CAST(lp.port AS TEXT) AS id, '' AS ver, p.path AS loc,
       lp.address AS extra, '' AS perms
  FROM listening_ports lp JOIN processes p USING (pid)
  WHERE lp.port > 0

UNION ALL

-- from running.sql
SELECT 'proc' AS kind,
       regex_match(exe || ' ' || cmdline,
                   'node_modules/((?:@[A-Za-z0-9][A-Za-z0-9._-]*/)?[A-Za-z0-9][A-Za-z0-9._-]*)', 1) AS id,
       '' AS ver, exe AS loc, '' AS extra, '' AS perms
  FROM (SELECT cmdline,
               CASE WHEN path != '' THEN path
                    ELSE substr(cmdline, 1, instr(cmdline || ' ', ' ') - 1) END AS exe
          FROM processes) p
  WHERE (exe LIKE '%/node_modules/%'
         OR ((exe LIKE '%/node' OR exe LIKE '%/nodejs' OR exe LIKE '%/bun' OR exe LIKE '%/deno'
              OR exe IN ('node', 'nodejs', 'bun', 'deno'))
             AND cmdline LIKE '%node_modules/%'))
    AND regex_match(exe || ' ' || cmdline,
                    'node_modules/((?:@[A-Za-z0-9][A-Za-z0-9._-]*/)?[A-Za-z0-9][A-Za-z0-9._-]*)', 1) IS NOT NULL
  -- One row per package and executable, however many workers it runs. GROUP BY rather than
  -- DISTINCT, because lint and tools/build.py find a branch's kind as `SELECT '<kind>'`.
  GROUP BY id, loc
UNION ALL
-- RUNNING FROM A HOME DIRECTORY, by executable path: Claude Code's native install runs from
-- ~/.local/share/claude/versions/<version>, not the ~/.local/bin/claude link `binaries`
-- names, so process_paths carries its own value. `path` only: an unreadable path leaves
-- argv[0], the launcher a user typed, which no value names.
SELECT 'proc', path, '', path, '', ''
  FROM processes
  WHERE path LIKE '/Users/%/%' OR path LIKE '/home/%/%' OR path LIKE '/root/%'
  GROUP BY path

UNION ALL

-- from runtime-linux.sql
SELECT 'unit' AS kind, id AS id, '' AS ver, fragment_path AS loc,
       unit_file_state AS extra, '' AS perms
  FROM systemd_units
UNION ALL
-- THE MARKER, a scan row in the spec's outcome vocabulary, reasoned from the UNIT COUNT:
-- a bus socket with nothing serving it still fails systemd_units, so presence alone would
-- report `ok` against a dead bus (Docker's `wedge` again).
--
--     units > 0            -> ok                  the rows above are real
--     no bus socket        -> absent              nothing to read
--     socket, but 0 units  -> unhealthy:no-units  no real systemd host has none
--
-- The subqueries sit in FROM, not the column list, because test/lint.sh reads a branch's
-- columns as the text between SELECT and the first FROM.
SELECT 'scan' AS kind, 'systemd' AS id, CAST(t.unix_time AS TEXT) AS ver,
       '/run/dbus/system_bus_socket' AS loc,
       CASE WHEN u.n > 0 THEN 'ok'
            WHEN s.n = 0 THEN 'absent'
            ELSE 'unhealthy:no-units' END AS extra,
       '' AS perms
  FROM time t,
       (SELECT COUNT(*) AS n FROM systemd_units) u,
       (SELECT COUNT(*) AS n FROM file
          WHERE path = '/run/dbus/system_bus_socket') s

UNION ALL

-- from vscode.sql
SELECT 'vscodeext' AS kind, name AS id, version AS ver, path AS loc,
       vscode_edition AS extra, '' AS perms
  FROM (SELECT uid FROM users
        UNION
        SELECT uid FROM file
         WHERE path LIKE '/home/%/' OR path = '/root/' OR path LIKE '/Users/%/') u
       CROSS JOIN vscode_extensions USING (uid);
